import{_ as r,C as t,c as n,o as s,aj as h,G as a,w as d}from"./chunks/framework.Bfdr4H5E.js";const l="/sk/images/Equity-SBIN-qty.webp",c="/sk/images/BN-Option-Chain-22jul.webp",p="/sk/images/Option-Strike-Price-3W-EG.webp",u="/sk/images/Bank-Nifty-Call-Spot-EG.webp",m="/sk/images/22-JUN-43500-CALL.webp",g="/sk/images/29-JUN-43500-CALL.webp",f="/sk/images/06-JUL-43500-CALL.webp",y="/sk/images/Bank-Nifty-Put-Spot-EG.webp",k="/sk/images/22-JUN-44200-PUT.webp",b="/sk/images/29-JUL-44200-PUT.webp",w="/sk/images/06-JUL-44200-PUT.webp",v="/sk/images/BankNifty-Spot-Chart-0623.webp",x="/sk/images/BNF-JUN-23.webp",I="/sk/images/BNF-JUL-23.webp",T="/sk/images/BNF-AUG-23.webp",C="/sk/images/Forex-Correlation-Table.webp",S="/sk/images/Pairs-with-Biggest-Market-Share.webp",N="/sk/images/Daily-Range-Table.webp",P="/sk/images/10-Cryptocurrencies-based-on-Market-Cap.webp",_=JSON.parse('{"title":"Market Segments Basics Explained","description":"","frontmatter":{"outline":"deep","prev":{"text":"Challenges and Difficulties","link":"/trading-with-pav/challenges-and-difficulties"},"next":{"text":"Finding Your Style","link":"/trading-with-pav/finding-your-style"}},"headers":[],"relativePath":"trading-with-pav/market-segments-basics-explained.md","filePath":"trading-with-pav/market-segments-basics-explained.md"}'),E={name:"trading-with-pav/market-segments-basics-explained.md"};function q(B,e,D,A,F,U){const i=t("GraphComment"),o=t("ClientOnly");return s(),n("div",null,[e[0]||(e[0]=h('<h1 id="market-segments-basics-explained" tabindex="-1">Market Segments Basics Explained <a class="header-anchor" href="#market-segments-basics-explained" aria-label="Permalink to &quot;Market Segments Basics Explained&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#market-segments-basics-explained-1">Market Segments Basics Explained</a><ul><li><a href="#what-is-an-equity-market">What Is an Equity Market?</a></li><li><a href="#what-is-an-index">What Is an Index?</a></li><li><a href="#derivatives-–-future-option-f-o">Derivatives – Future &amp; Option (F&amp;O)</a></li><li><a href="#commodities-derivatives">Commodities (Derivatives)</a></li><li><a href="#currency-derivatives">Currency (Derivatives)</a></li><li><a href="#forex-market">Forex Market</a></li><li><a href="#best-cryptocurrencies-to-trade">Best cryptocurrencies to trade</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="market-segments-basics-explained-1" tabindex="-1">Market Segments Basics Explained <a class="header-anchor" href="#market-segments-basics-explained-1" aria-label="Permalink to &quot;Market Segments Basics Explained&quot;">​</a></h2><p>As you learned in previous article called <a href="/sk/trading-with-pav/market-segments/">Market Segments</a> there are 6 segments out of which 4 segments can be officially traded in India. Those are as follows:</p><ol><li>Equity</li><li>Equity Derivatives (Future and Options)</li><li>Currency Derivatives (Future and Options) country-wise</li><li>Commodities Derivatives (Future and Options)</li></ol><p>Lets start with Equity.</p><h3 id="what-is-an-equity-market" tabindex="-1">What Is an Equity Market? <a class="header-anchor" href="#what-is-an-equity-market" aria-label="Permalink to &quot;What Is an Equity Market?&quot;">​</a></h3><p>An equity market is a market in which shares of companies are issued and traded, either through exchanges or over-the-counter markets. Also known as the stock market, it is one of the most vital areas of a market economy. It gives companies access to capital to grow their business, and investors a piece of ownership in a company with the potential to realize gains in their investment based on the company’s future performance.</p><p>Equity markets are the meeting point for buyers and sellers of stocks. The securities traded in the equity market can either be public stocks, which are those listed on the stock exchange, or privately traded stocks. Often, private stocks are traded through dealers, which is the definition of an over-the-counter market.</p><p>When companies are born they are private companies, and after a certain time, they go through an initial public offering (IPO), which is a process that turns them into public companies traded on a stock exchange. Private stocks operate slightly differently as they are only offered to employees and certain investors.</p><p>Some of the largest equity markets, or stock markets, in the world are the New York Stock Exchange, Nasdaq, Tokyo Stock Exchange, Shanghai Stock Exchange, Bombay Stock Exchange and Euronext Europe.</p><p>Companies list their stocks on an exchange as a way to obtain capital to grow their business. An equity market is a form of equity financing, in which a company gives up a certain percentage of ownership in exchange for capital. That capital is then used for a variety of business needs. Equity financing is the opposite of debt financing, which utilizes loans and other forms of borrowing to obtain capital.</p><h4 id="trading-in-an-equity-market" tabindex="-1">Trading in an Equity Market <a class="header-anchor" href="#trading-in-an-equity-market" aria-label="Permalink to &quot;Trading in an Equity Market&quot;">​</a></h4><p>In India you can trade through NSE or BSE. This article will deal with NSE only though both work the same. In NSE there are more or less 1,800 companies listed are tradeable by public.</p><p>The below chart is of State Bank of India which symbol is SBIN.</p><p><img src="'+l+'" alt="Equity-SBIN-qty"></p><p>You can basically see that the lowest quantity traded is 1 Shares x 568.05 = 568.05 but as you can see in the buy window it shows 568.2 which is Total tax &amp; charges included as shown in Price breakup which is 0.68 (Price breakup in above is delayed Screenshot edited and pasted for demonstration purpose).</p><p>This is a list of companies listed on the <a href="https://en.wikipedia.org/wiki/List_of_companies_listed_on_the_National_Stock_Exchange_of_India" target="_blank" rel="noreferrer">National Stock Exchange of India</a> (NSE). You can trade whatever interests you according to our analysis.</p><h3 id="what-is-an-index" tabindex="-1">What Is an Index? <a class="header-anchor" href="#what-is-an-index" aria-label="Permalink to &quot;What Is an Index?&quot;">​</a></h3><p>An index is a method to track the performance of a group of assets in a standardized way. Indexes typically measure the performance of a basket of securities (stocks) intended to replicate a certain area of the market.</p><p>These could be constructed as a broad-based index that captures the entire market, such as the Nifty 50 Index or Dow Jones Industrial Average (DJIA), or more specialized such as indexes that track a particular industry or segment such as Bank Nifty Index, which tracks only Finance stocks.</p><h4 id="nifty-50" tabindex="-1">Nifty 50 <a class="header-anchor" href="#nifty-50" aria-label="Permalink to &quot;Nifty 50&quot;">​</a></h4><p>The NIFTY 50 is a benchmark Indian stock market index that represents the weighted average of 50 of the largest Indian companies listed on the National Stock Exchange.</p><p>Nifty 50 is owned and managed by NSE Indices (previously known as India Index Services &amp; Products Limited), which is a wholly owned subsidiary of the NSE Strategic Investment Corporation Limited. NSE Indices had a marketing and licensing agreement with Standard &amp; Poor’s for co-branding equity indices until 2013. The Nifty 50 index was launched on 22 April 1996, and is one of the many stock indices of Nifty.</p><p>The NIFTY 50 index has shaped up to be the largest single financial product in India, with an ecosystem consisting of exchange-traded funds (onshore and offshore), and futures and options at NSE and SGX. NIFTY 50 is the world’s most actively traded contract. WFE, IOM and FIA surveys endorse NSE’s leadership position. Between 2008 &amp; 2012, the NIFTY 50 index’s share of NSE market fell from 65% to 29% due to the rise of sectoral indices like NIFTY Bank, NIFTY IT, NIFTY Pharma, and NIFTY Next 50.</p><p>The NIFTY 50 index covers 15 sectors of the Indian economy and offers investment managers exposure to the Indian market in one portfolio.</p><p>As of June 30, 2025 NIFTY 50 gives a weightage (Sector Representation) as follows:</p><table tabindex="0"><thead><tr><th>Sector</th><th>Weight(%)</th></tr></thead><tbody><tr><td>Financial Services</td><td>37.41</td></tr><tr><td>Information Technology</td><td>11.21</td></tr><tr><td>Oil, Gas &amp; Consumable Fuels</td><td>10.38</td></tr><tr><td>Automobile and Auto Components</td><td>7.03</td></tr><tr><td>Fast Moving Consumer Goods</td><td>6.50</td></tr><tr><td>Telecommunication</td><td>4.74</td></tr><tr><td>Construction</td><td>3.73</td></tr><tr><td>Healthcare</td><td>3.60</td></tr><tr><td>Metals &amp; Mining</td><td>3.44</td></tr><tr><td>Consumer Services</td><td>2.78</td></tr><tr><td>Power</td><td>2.55</td></tr><tr><td>Consumer Durables</td><td>2.23</td></tr><tr><td>Construction Materials</td><td>2.18</td></tr><tr><td>Capital Goods</td><td>1.31</td></tr><tr><td>Services</td><td>0.93</td></tr></tbody></table><h4 id="what-are-constituents" tabindex="-1">What are constituents? <a class="header-anchor" href="#what-are-constituents" aria-label="Permalink to &quot;What are constituents?&quot;">​</a></h4><p>A constituent is a company whose shares are the part of the index and are used to calculate the index value. The weight that each constituent has on the overall index is based on market capitalisation. Index weight represents the share percentage of constituents in the index. Contribution change measures the contribution of each constituent towards the movements in the index value.</p><p>Nifty 50 constituents (stocks sector wise) as of 28 March 2025 are listed <a href="https://en.wikipedia.org/wiki/NIFTY_50#Constituents" target="_blank" rel="noreferrer">here</a>.</p><h4 id="nifty-bank" tabindex="-1">Nifty Bank <a class="header-anchor" href="#nifty-bank" aria-label="Permalink to &quot;Nifty Bank&quot;">​</a></h4><p>NIFTY Bank is sectoral index based of finance stocks.</p><p>The Nifty Bank Index comprises of the most liquid and large Indian Banking stocks. It provides investors and market intermediaries a benchmark that captures the capital market performance of the Indian banks. The Index comprises of maximum 12 companies listed on National Stock Exchange of India (NSE).</p><p>Nifty Bank Index is computed using free float market capitalization method. Nifty Bank Index can be used for a variety of purposes such as benchmarking fund portfolios, launching of index funds, ETFs and structured products.</p><p>Nifty Bank constituents as of July 14, 2025 are listed below</p><table tabindex="0"><thead><tr><th><strong>NIFTY BANK Stocks</strong></th><th><strong>Index weight 100%</strong></th></tr></thead><tbody><tr><td>HDFC Bank Ltd.</td><td>39.78</td></tr><tr><td>ICICI Bank Ltd.</td><td>26.68</td></tr><tr><td>Axis Bank Ltd.</td><td>8.82</td></tr><tr><td>Kotak Mahindra Bank Ltd.</td><td>8.58</td></tr><tr><td>State Bank of India</td><td>8.18</td></tr><tr><td>IndusInd Bank Ltd.</td><td>1.49</td></tr><tr><td>Federal Bank Ltd.</td><td>1.34</td></tr><tr><td>AU Small Finance Bank Ltd.</td><td>1.21</td></tr><tr><td>Bank of Baroda</td><td>1.16</td></tr><tr><td>Canara Bank</td><td>0.99</td></tr><tr><td>Punjab National Bank</td><td>0.90</td></tr><tr><td>IDFC First Bank Ltd.</td><td>0.87</td></tr></tbody></table><p>So now that you know Indices, how do we trade them? We trade them through Futures and Option.</p><h3 id="derivatives-–-future-option-f-o" tabindex="-1">Derivatives – Future &amp; Option (F&amp;O) <a class="header-anchor" href="#derivatives-–-future-option-f-o" aria-label="Permalink to &quot;Derivatives – Future &amp; Option (F&amp;O)&quot;">​</a></h3><p>Futures and Options are two types of derivatives contracts that derive their value from market movements for the underlying <strong>index</strong>, <strong>security</strong> or <strong>commodity</strong>.</p><p>An option gives the buyer the right, but not the obligation, to buy (or sell) an asset at a specific price at any time during the life of the contract.</p><p>A futures contract obligates the buyer to purchase a specific asset, and the seller to sell and deliver that asset, at a specific future date, unless the holder’s position is closed earlier.</p><p>Futures and options positions may be traded and closed ahead of expiration, but the parties to the futures contracts for commodities are typically obligated to make and accept deliveries on the settlement date.</p><p>But there are important differences in the rules for options and futures contracts, and in the risks they pose to investors.</p><h4 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h4><p>There are only two kinds of options: <strong>Call</strong> options and <strong>Put</strong> options.</p><p>A <strong>call</strong> option confers the right to buy a stock at the strike price before the agreement expires.<br> A <strong>put</strong> option gives the holder the right to sell a stock at a specific price.</p><h5 id="option-simplified" tabindex="-1">Option Simplified <a class="header-anchor" href="#option-simplified" aria-label="Permalink to &quot;Option Simplified&quot;">​</a></h5><p>An option is a contract giving the buyer the right, but not the obligation, to buy or sell an underlying asset (a stock or index). There are only two kinds of options: <strong>Call</strong> options and <strong>Put</strong> options.</p><p>At the time of agreement(buying an option) the option buyer pays a certain amount to the option seller, this is called the ‘<strong>Premium</strong>’ amount.</p><p>The agreement happens at a pre specified price, often called the ‘<strong>Strike Price</strong>’. The directional view has to pan out before the expiry date, else the option will <strong>expire</strong> worthless.</p><h5 id="lot-sizes-of-option" tabindex="-1">Lot Sizes of Option <a class="header-anchor" href="#lot-sizes-of-option" aria-label="Permalink to &quot;Lot Sizes of Option&quot;">​</a></h5><p>Nifty lot size 50<br> Expiry weekly every Thursday.</p><p>BankNifty lot size 15<br> Expiry weekly every Friday.</p><p>Equity (stocks)<br> Lot size depends on each stock<br> Expiry monthly last Thursday of month</p><p>When market goes up <strong>Call increases</strong> when market goes down <strong>Put increases</strong> and <strong>vise versa</strong>.</p><h4 id="option-chain" tabindex="-1">Option Chain <a class="header-anchor" href="#option-chain" aria-label="Permalink to &quot;Option Chain&quot;">​</a></h4><p>Options trade on the open market just as stocks do, however there are additional data points displayed that are specific to options – this is depicted on the option chain. An option chain is utilized by investors to view the pricing and activity of all of the listed options for the selected underlying.</p><p><img src="'+c+'" alt="BN-Option-Chain-22jul"></p><p>The above image shows option chain of BankNifty of 22 June 2023 Expiry. lets explorer all the terminology in the option chain.</p><h5 id="how-is-the-option-chain-organized" tabindex="-1">How is the option chain organized? <a class="header-anchor" href="#how-is-the-option-chain-organized" aria-label="Permalink to &quot;How is the option chain organized?&quot;">​</a></h5><p><strong>Calls and Puts</strong> : Options chains are normally broken down into two sections, calls and puts. Calls are displayed on the left and puts on the right. Purchasers of call contracts own the right to buy and sellers of call contracts have the obligation to sell. Purchasers of put contracts own the right to sell and sellers of put contracts have the obligation to buy.</p><p><strong>Strike Price</strong> : The strike price is typically displayed in the center column of the option chain. This is the price at which the put or call can be exercised.</p><p><strong>Expiration Date</strong> : The option chain is by default sorted by expiration date with the options expiring first at the top. The expiration date will determine how long the contract is in existence. This is sometimes depicted as days to expiration (DTE). The above Option chain chart is 22 June 2023 expiry.</p><p><strong>Color Coding</strong> : Options that are not highlighted ‘white’ are <strong>in-the-money</strong> and options that are highlighted ‘brown grey’ are <strong>out-the-money</strong>.<br> (Calls are in-the-money when the strike price is below the market price of the underlying. Puts are in-the-money when the strike price is above the market price of the underlying).<br> The color coding is used to easily see what is in, out, or <strong>near (At) the money</strong>.</p><h5 id="what-do-all-the-quote-details-mean" tabindex="-1">What do all the quote details mean? <a class="header-anchor" href="#what-do-all-the-quote-details-mean" aria-label="Permalink to &quot;What do all the quote details mean?&quot;">​</a></h5><p><strong>Last Traded Price</strong> (<strong>LTP</strong>) : The last price represents the last price at which the option was traded. This could be an opening or a closing transaction. It is important to note that the last time an option was traded could be within seconds, minutes, days, weeks, or even months and may not be an accurate depiction of the current value of the option. The last price in conjunction with the bid and ask is used to quote the value of the option.</p><p><strong>Change</strong> : The change displays the difference of the last price and previous day’s close.</p><p><strong>Bid</strong> : The bid represents the best available price that the option can be sold for.</p><p><strong>Ask</strong> : The ask represents the best available price that the option can be purchased for.</p><p><strong>Volume</strong> : Volume represents the amount of transactions that have occurred on the current trading day. This figure will update intra-day and is used in conjunction with open interest to determine if the options contract is considered liquid. (Most options do not trade through the extended hours therefore, previous day information may be displayed prior to the market opening) Any option transaction regardless if it is opening or closing will be reflected in the volume.</p><p><strong>Open Interest</strong> : Open interest shows the amount of contracts in existence for the option. This figure is only updated once a day and will differ from volume. At the end of the trading day all contracts that were closed are subtracted from open interest and all contracts that were open are added to open interest. In short OI indicates the total number of options contracts that are currently open in the market.</p><p><strong>Implied Volatility</strong> (<strong>IV</strong>): Implied volatility is an estimate of the future volatility, or fluctuations, of an option’s price. It only forecasts the sizes of potential price swings.</p><p><strong>Delta</strong> : It measures how much an option price changes for a one-point move in the underlying. Its value ranges between O and 1 for calls.<br> For put side delta It measures how much an option price changes for a one-point move in the underlying. Its value ranges between l and O for puts</p><p><strong>Theta</strong> : Theta measures the rate of time value decay and it is always a negative number as time moves in only one direction.</p><p><strong>Gamma</strong> : It measures the rate of change in the delta. values are highest for at-the-money options and smallest for those far in or out of the money.</p><p><strong>Vega</strong> : Vega measures the risk from changes in implied volatility. Higher volatility makes options more expensive since there is a greater chance that the underlying security price will move above or below.</p><h5 id="trading-the-options" tabindex="-1">Trading the Options <a class="header-anchor" href="#trading-the-options" aria-label="Permalink to &quot;Trading the Options&quot;">​</a></h5><p>The best and simplest way to trade option is through our strategy as our high probability setups where price from S/R moves drastically one side. The key to be in profit is drastic move cuz any sideways move will decay the price (theta).</p><p><img src="'+p+'" alt="Option-Strike-Price-3W-EG"></p><p>The above image shows 3 Expires of BankNifty options dated 22 June, a week later 29 June, and a week later 06 Jul 2023 taken after market closed on 16 Jun 2023. You can see that on 16 Jun market opened at 43583.35 and closed at 43938.15 i.e. BankNifty price raised 354.8 points.</p><p>As there was bullish move whole day you can see below the Call OTM (Out the Money) Strike Prices have risen as follows:</p><ul><li>Current expiry 22 June 2023 has increase by 80% than previous day price.</li><li>Next week expiry 29 June 2023 has increase 53% than previous day price.</li><li>06 July 2023 has increase by 40% than previous day price.</li><li><strong>Most highest increase i.e. 84~88% was at 43,700 and 43,800 strike which is 2 or 3 strike price above the ATM for call</strong> (<strong>vice versa</strong> <strong>for Put</strong>).</li></ul><table tabindex="0"><thead><tr><th><strong>Strike Price</strong></th><th><strong>LTP</strong> (<strong>22 June 23</strong>)</th><th><strong>LTP</strong> (<strong>29 Jun 23</strong>)</th><th><strong>LTP</strong> (<strong>06 Jul 23</strong>)</th></tr></thead><tbody><tr><td>43,500</td><td>546 (77.30%)</td><td>692 (50.52%)</td><td>809.95 (37.89%)</td></tr><tr><td>43,600</td><td>470 (82.49%)</td><td>612.70 (51.17%)</td><td>725.70 (-51.19%)</td></tr><tr><td><strong>43,700</strong></td><td>393 (84.94%)</td><td>544.55 (53.57%)</td><td>674.20 (41.40%)</td></tr><tr><td><strong>43,800</strong></td><td>325 (<strong>88.62</strong>%)</td><td>479.25 (<strong>53.38</strong>%)</td><td>607.65 (<strong>40.97</strong>%)</td></tr><tr><td>43,900</td><td>255 (83.57%)</td><td>419.70 (55.62%)</td><td>559.35 (46.27%)</td></tr></tbody></table><p><strong>Call</strong> OTM Comparison</p><p>Bank Nifty <strong>LTP</strong> is 43.938.15 is <strong>ATM</strong> or <strong>ITM</strong>.</p><table tabindex="0"><thead><tr><th><strong>Strike Price</strong></th><th><strong>LTP</strong> (<strong>22 June 23</strong>)</th><th><strong>LTP</strong> (<strong>29 Jun 23</strong>)</th><th><strong>LTP</strong> (<strong>06 Jul 23</strong>)</th></tr></thead><tbody><tr><td>44,000</td><td>234.70 (-60.27%)</td><td>353 (-46.62%)</td><td>447.95 (-39.31%)</td></tr><tr><td>44,100</td><td>287.70 (-56.85%)</td><td>405.85 (-44.34%)</td><td>535.60 (-33.07%)</td></tr><tr><td><strong>44,200</strong></td><td>342.00 (-53.84%)</td><td>458.75 (-42.20%)</td><td>523.95 (-39.96%)</td></tr><tr><td><strong>44,300</strong></td><td>415.20 (-49.73%)</td><td>516.90 (-40.63%)</td><td>629.25 (-33.45%)</td></tr><tr><td>44,400</td><td>487.05 (-47.19%)</td><td>574.60 (-39.16%)</td><td>642.45 (-27.54%)</td></tr></tbody></table><p><strong>Put</strong> OTM Comparison</p><p>IMPORTANT NOTE</p><p>You are free to choose any strike price or tweak the strike price selecting process from this example. The example shown here is the process I use for myself which I concluded doing testing on different strike price on directional price movement.</p><p>You should also do the same. Nothing is perfect in trading its Dynamics flow. Even I might tweak my Option Strike selecting process according to my observation.</p><p>Because option prices are constantly affected by options Greeks like Delta, Gamma, Vega, Theta and the natural demand supply situation of the markets influence each other. Though all these factors work as independent agents, yet they are all intervened with one another.</p><p>Explore more <a href="https://zerodha.com/varsity/module/option-theory/" target="_blank" rel="noreferrer">HERE</a>.</p><p>Lets look at Call and Put scenarios. Below chart is of Nifty Bank Index Chart where we can see that the resistance has been tested and @14:37 pm there was a pullback entry for up trend. As I have mentioned above for selecting Optimum CALL we have to select 2 or 3 strike below the ATM. The current price at Entry is 43768 which means our strike price for CALL is 43500 of 22 JUN 2023 Expiry.</p><p><img src="'+u+'" alt="Bank-Nifty-Call-Spot-EG"></p><p>Nifty Bank Spot Chart</p><p>In the above Spot chart price went from 43768.60 to 44060.00 directional movement was fast within 14 min we got 291.4 pts. Below is Current Week Expiry i.e. 22 JUN 43500 CALL. Entry price was 458.05 till 14:52 where price reached 714 that’s 256/- profit in 14 min.</p><p>One thing to remember is until you are beginner trade current expiry and switch to next expiry on one day before expiry to next week expiry.</p><p><img src="'+m+'" alt="22-JUN-43500-CALL"></p><p>22 JUN 43500 CALL</p><p>Below is next week expiry i.e. 29 JUN 43500 CALL here same condition but profit is 238.35/-. As you can see less than current week and market is volatile as there are gaps in candle. Only to enter this expiry a day before current expiry.</p><p><img src="'+g+'" alt=""></p><p>29 JUN 43500 CALL</p><p>Now below is far week expiry 06 JUL 43500 CALL here profit for same condition is 232.85 less than next week but not that much. As you can witness in below chart there is no volume and volatile market with gaps.</p><p><img src="'+f+'" alt="06-JUL-43500-CALL"></p><p>06 JUL 43500 CALL</p><p>Now lets look at PUT scenario Entry price of Spot is 44060 which means our strike price is 44200 OTM. Also you can see that the price had lot of resistance going down then up direction plus it took 18 min to get 44060-43840=220 pts. Less Points then up direction but took more time.</p><p>Lets look at how our current expiry has performed.</p><p><img src="'+y+'" alt="Bank-Nifty-Put-Spot-EG"></p><p>Nifty Bank Spot Chart</p><p>As you can see in the below chart we got 154.90/- which is less than the above BN movement so remember for option price to travel greater distance the Spot Price should travel with least amount of resistance and any sideways moment in the trend might slow the option price.</p><p><img src="'+k+'" alt="22-JUN-44200-PUT"></p><p>22 JUN 44200 PUT</p><p>As Spot price had difficulties that will affect more for Next week expiry as shown below we got 134.15/- for 29 JUN 44200 PUT plus its volatile with gaps in candles.</p><p><img src="'+b+'" alt="29-JUL-44200-PUT"></p><p>29 JUN 44200 PUT</p><p>The far week expiry with mixture of volatility and less volume it gave 117.10/- option price points for Spot price movement of 220 pts.</p><p>Now you know how option trading works which strike to chose with expiry in mind observe various Spot movements and compare option price and tweak this setup process as it seems to fit your psychology.</p><p><img src="'+w+'" alt="06-JUL-44200-PUT"></p><p>06 JUL 44200 PUT</p><p>That’s it for Option Trading. Lets move to Futures.</p><h4 id="futures" tabindex="-1">Futures <a class="header-anchor" href="#futures" aria-label="Permalink to &quot;Futures&quot;">​</a></h4><p>The futures market is regulated by SEBI in India. Lot size is the minimum quantity specified in the futures contract.</p><h5 id="what-is-spot-price" tabindex="-1">What Is Spot Price? <a class="header-anchor" href="#what-is-spot-price" aria-label="Permalink to &quot;What Is Spot Price?&quot;">​</a></h5><p><strong>The price at which a stock, currency, or commodity is traded for immediate delivery or settlement is referred to as the spot price</strong>. Participants use this price to buy or sell the instruments at any given period of time.</p><p>The current or the spot price of the instrument is determined by the level of demand and supply during the current period.</p><h5 id="what-is-the-futures-price" tabindex="-1">What Is the Futures Price? <a class="header-anchor" href="#what-is-the-futures-price" aria-label="Permalink to &quot;What Is the Futures Price?&quot;">​</a></h5><p><strong>The futures price is the one that is mentioned in the futures contract</strong>. Usually, this price moves in sync with the spot price of the underlying security. But this price can differ from the spot price in the market due to interest rates, dividends, and time to expiry.</p><p>The futures price and the spot price of an asset are different</p><ul><li>Contract value = Lot size times the Futures price</li></ul><p>To enter into a futures agreement one has to deposit a margin amount, which is a certain % of the contract value. One lot refers to the minimum number of shares that needs to be transacted.</p><p>Once we enter into a futures agreement there is no obligation to stick to the agreement until the contract expires.</p><p>Every futures contract has an expiry date beyond which the contact would seize to exist. Upon expiry old contracts cease and new ones are created.</p><p>Every futures trade requires a margin amount, the margins are blocked the moment you enter a futures trade. We can exit the agreement anytime, which means you can exit the agreement within seconds of entering the agreement.</p><p>Once we square off the futures position, margins are unblocked. The money that you make or lose in a futures transaction is credited or debited to your trading account.</p><p>For future buy and future short margin required is same.</p><h5 id="what-is-premium-in-futures-market" tabindex="-1">What Is Premium In Futures Market: <a class="header-anchor" href="#what-is-premium-in-futures-market" aria-label="Permalink to &quot;What Is Premium In Futures Market:&quot;">​</a></h5><p>When the value of a futures contract trades at more amount than the spot price of the underlying on which the contract is based, it is referred to as the Premium. When this phenomenon occurs in any derivatives market, it is referred to as ‘Contango’.</p><p><strong>For example</strong>, The spot price of gold is trading at Rs. 61000 for 10 grams and the futures contract is trading at Rs. 61500. This means the value of the futures contract is trading at a premium of Rs.500.</p><p><strong>The factors that cause a Premium in the futures market:</strong></p><ul><li><strong>Increase in demand for the contract:</strong> The expectations of the market participants are one of the factors that cause the futures contract to trade at a premium.</li></ul><p>If there are expectations for the price of the underlying asset to increase in the future, more participants will try buying the futures contracts which results in excess demand over the supply. This results in the contract trading at a premium.</p><ul><li><strong>Increase in the cost of storage:</strong> Another factor that can cause a premium in the futures contract is the cost of storage. That is the cost incurred to store a particular commodity.</li></ul><p>Let us understand this with the help of an example:</p><p>Suppose you require a particular commodity that will be deliverable to you in three months. As the commodity is deliverable to you on a future date, you are required to pay the seller for the storage of the commodity which causes a premium in the futures price.</p><h5 id="what-is-discount-in-futures-market" tabindex="-1">What Is Discount In Futures Market: <a class="header-anchor" href="#what-is-discount-in-futures-market" aria-label="Permalink to &quot;What Is Discount In Futures Market:&quot;">​</a></h5><p>When the value of a futures contract trades is lesser than the spot price of the underlying, it is referred to as a discount. When this phenomenon occurs in the commodity derivatives market, it is referred to as ‘Backwardation’’.</p><p><strong>For example,</strong> The spot price of gold is trading at Rs. 61000 for 10 grams and the futures contract is trading at Rs. 60500. This means the value of the futures contract is trading at a discount of Rs.500.</p><p><strong>The factors that cause a discount in the futures market:</strong></p><ul><li><strong>Decrease in demand for the contract:</strong> If there are expectations for the price of the underlying asset to decrease in the future, participants will choose alternative options that are safer or that have the potential to give better returns, This decreases the demand for the contract which in turn causes the futures contract to trade at a discount.</li><li><strong>Short-Term Demand spikes:</strong> An increase in the demand in the near term can also cause a discount in the futures contract. For instance, there’s a short-term surge in the demand for coffee beans and its demand is expected to return to normal in the future. This will result in the spot price trading at more rate than the futures price.</li></ul><h5 id="what-does-premium-and-discount-in-futures-market-tell-you" tabindex="-1">What Does Premium And Discount In Futures Market Tell You? <a class="header-anchor" href="#what-does-premium-and-discount-in-futures-market-tell-you" aria-label="Permalink to &quot;What Does Premium And Discount In Futures Market Tell You?&quot;">​</a></h5><p>When a futures contract is trading at a high premium, it is an indication that the price of the underlying asset <strong>may</strong> increase in the future. In this situation, one can take a long position in the underlying security.</p><p>When a futures contract is trading at a huge discount, it is an indication that the price of the underlying asset <strong>may</strong> decrease in the future. In this situation, one can take a short position in the underlying security.</p><p><strong>Note</strong>: The above info should be only used as confluence to our Strategies not standalone.</p><p>On the day of expiry the future and spot will always converge.</p><h5 id="examples-of-bank-nifty-futures" tabindex="-1">Examples Of Bank Nifty Futures <a class="header-anchor" href="#examples-of-bank-nifty-futures" aria-label="Permalink to &quot;Examples Of Bank Nifty Futures&quot;">​</a></h5><p>Below is BankNifty Index Chart aka Spot Chart for BNF and the Spot price is 43796.50.</p><p><img src="'+v+'" alt="BankNifty-Spot-Chart-0623"></p><p>BankNifty Index Chart (Spot Chart)</p><p>Below is Near Month Expiry chart which is JUN 23 and the price is 43875.10 i.e. Premium of 78.6.<br> Lot size and brokerage is displayed on order window.</p><p><img src="'+x+'" alt="BNF-JUN-23"></p><p>BankNifty JUN Futures</p><p>After near month expiry comes Next Month Expiry which is JUL 23 and the price is 44025 i.e. Premium of 228.5.</p><p><img src="'+I+'" alt="BNF-JUL-23"></p><p>BankNifty JUL Futures</p><p>After next month expiry comes Far Month Expiry which is JUL 23 and the price is 44239 i.e. Premium of 442.5.</p><p><img src="'+T+'" alt="BNF-AUG-23"></p><p>BankNifty AUG Futures</p><h3 id="commodities-derivatives" tabindex="-1">Commodities (Derivatives) <a class="header-anchor" href="#commodities-derivatives" aria-label="Permalink to &quot;Commodities (Derivatives)&quot;">​</a></h3><p>A commodity trading market is a marketplace where you can buy, sell and trade in commodities. The commodity trading market can be both physical and virtual (stock exchange).</p><p>There are 4 types of commodities which can be traded in a commodity trading market:</p><ul><li><strong>Metals</strong> – Gold, Silver, Platinum, Copper etc.</li><li><strong>Energy</strong> – Crude oil, Gasoline, Heating gas etc.</li><li><strong>Agriculture</strong> – Wheat, Rice, Cocoa, Ragi etc.</li><li><strong>Livestock &amp; Meat</strong> – Eggs, Cattle etc.</li></ul><p>Commodity trading has been happening in India since ancient times; however, poor government policies, fragmented markets and foreign invasions reduced its popularity.</p><p>But with the introduction of exchanges like <strong><a href="https://www.mcxindia.com/" target="_blank" rel="noreferrer">MCX</a></strong> and <strong><a href="https://www.ncdex.com/" target="_blank" rel="noreferrer">NCDEX</a></strong> commodity trading in India is regaining its importance and popularity.</p><h4 id="where-does-commodity-trading-take-place-in-india" tabindex="-1">Where does commodity trading take place in India? <a class="header-anchor" href="#where-does-commodity-trading-take-place-in-india" aria-label="Permalink to &quot;Where does commodity trading take place in India?&quot;">​</a></h4><p>There are 4 major commodity trading exchanges in India:</p><ul><li><strong>Multi Commodity Exchange of India, MCX</strong></li><li><strong>National Commodities and Derivatives Exchange Limited, NCDEX</strong></li><li><strong>Indian Commodity Exchange, ICEX</strong></li><li><strong>National Multi Commodity Exchange of India, NMCX</strong></li></ul><p>The commodity trading market in India is an electronic trading platform for market participants to buy and sell commodities.  The two main commodity trading markets in India:</p><ul><li><strong>Multi Commodity Exchange of India, MCX</strong></li><li><strong>National Commodities and Derivatives Exchange Limited, NCDEX</strong></li></ul><p>Both MCX and NCDEX are online commodity exchanges which help market participants to trade in precious metals, agricultural products and energy products.</p><h4 id="types-of-commodities-traded-in-india-on-mcx" tabindex="-1">Types of commodities traded in India on MCX <a class="header-anchor" href="#types-of-commodities-traded-in-india-on-mcx" aria-label="Permalink to &quot;Types of commodities traded in India on MCX&quot;">​</a></h4><ul><li>Bullion like Gold, Silver, Platinum</li><li>Energy like natural gas, crude oil, gasoline</li><li>Agricultural products like castor seeds, cardamom, black pepper, cotton.</li><li>Metals like lead, zinc, copper, nickel</li></ul><p>Complete list of commodities available on MCX to trade; can be found in your brokage calculator.</p><p>While, MCX is the largest commodity trading market in India, since 2003, NCDEX has started picking up pace and is currently the largest commodity trading market in India in terms of volume.</p><p>But commodity trading is not new in India. The commodity trading market in India has a rich history which dates back to 1875 with the establishment of Bombay Cotton Trade Association.</p><p>But a world war, fight for independence and poor government strategy, resulted in stagnant growth of the commodity trading market in India.</p><p>But with the establishment of NCDEX, one of the leading commodity exchanges in India, commodity trading has started picking up pace.</p><p>NCDEX is a leading agricultural commodity exchange in India with an average daily turnover of Rs 1,18,163.78 Lakhs in 2020, much higher than the Rs 11,318.05 Lakhs in 2003.</p><p>The full form of NCDEX is <strong>National Commodity &amp; Derivatives Exchange Limited</strong>. NCDEX was incorporated as a public limited company on 23rd April 2003 and began operations on 9th May 2003.</p><p>NCDEX was recognized as a deemed stock exchange on 28th September 2015 under the Securities Contracts (Regulation Act), 1956.</p><p>NCDEX is regulated by SEBI and is headquartered in Mumbai. NCDEX allows trading in 23 commodities; highest across the global commodities market.</p><h4 id="types-of-commodities-traded-in-india-on-ncdex" tabindex="-1">Types of commodities traded in India on NCDEX? <a class="header-anchor" href="#types-of-commodities-traded-in-india-on-ncdex" aria-label="Permalink to &quot;Types of commodities traded in India on NCDEX?&quot;">​</a></h4><p>The NCDEX allows trading in 23 commodities, highest among all commodity trading markets.</p><ul><li><strong>Cereal &amp; Pulses</strong>: Chana, Barley, Bajra, Wheat, Moong, Maize, Paddy(Basmati).</li><li><strong>Fiber’s</strong>: Kapas, 29mm Cotton</li><li><strong>Spices</strong>: Turmeric, Coriander, Jeera</li><li><strong>Oil &amp; Oil Seeds</strong>: Castor oil, cotton seed oil cake, soybean, refined soy oil, mustard seed, crude palm oil, sesame seeds</li><li><strong>Soft</strong>: Gur</li><li><strong>Guar complex</strong>: Guar seed (10 MT), Guar gum refined splits.</li><li><strong>Index products</strong>: AGRIDEX</li></ul><p>Similar to NSE’s Nifty50 and BSE’s SENSEX, even NCDEX has a benchmark index known as NCDEX AGRIDEX.</p><p>While SENSEX tracks the performance of top 30 stocks, NCDEX AGRIDEX tracks the performance of 10 most liquid commodities on the NCDEX platform like Chana, Gaur Seeds, Soybean etc.</p><p>Apart from commodities, NCDEX also NCDEX rain index and NCDEX monsoon index tracking Indian monsoon between 1st June – 30th September every year.</p><h4 id="participants-in-commodity-markets-in-india" tabindex="-1">Participants in commodity markets in India? <a class="header-anchor" href="#participants-in-commodity-markets-in-india" aria-label="Permalink to &quot;Participants in commodity markets in India?&quot;">​</a></h4><p>Like the stock market, the commodity trading market is also dominated by:</p><ul><li>Hedgers</li><li>Speculators</li></ul><p><strong>1. Hedgers</strong>: Hedgers are producers, manufacturers, etc. who participate in the commodity trading market only to hedge their risk. Their aim is to reduce risk, not make profits.</p><p>For example: A rice farmer wants to hedge the price risk on his produce. So, he enters into a futures contract. Now, if the price of rice falls in the local market, he can sell his futures contract and make profit. In case the price rises, he can sell the produce at a higher price in the local market.</p><p>This way farmers, manufacturers hedge their risk in the commodity markets.</p><p><strong>2. Speculators:</strong> Speculators are traders who simply speculate on the price of the commodity. Speculators aim to generate short term profits through commodity trading. They do not face any risk, which needs hedging. For example, Ravi expects that the price of rice will go up in the coming months. So, he buys a rice futures contract and sells when the price increases. This way, he makes a profit without taking any long term positions or physical delivery.</p><h4 id="should-you-trade-in-commodity-markets-in-india" tabindex="-1">Should you trade in commodity markets in India? <a class="header-anchor" href="#should-you-trade-in-commodity-markets-in-india" aria-label="Permalink to &quot;Should you trade in commodity markets in India?&quot;">​</a></h4><p>Commodities markets are the perfect way for you to hedge your equity portfolio. Commodities and equities have a negative correlation. So, when equity markets fall, commodity markets rise and vice-a-versa.</p><p>Hence commodity trading helps you manage the stock market risks. Certain commodities like crude oil, gold, copper offer high trading volumes.</p><h4 id="the-importance-of-a-commodity-trading-market" tabindex="-1">The importance of a commodity trading market? <a class="header-anchor" href="#the-importance-of-a-commodity-trading-market" aria-label="Permalink to &quot;The importance of a commodity trading market?&quot;">​</a></h4><p>Commodity trading market has provided an exchange platform for market participants where real price discovery of commodities can take place. Let’s look at the importance of commodity trading markets in India.</p><p><strong>1. Real Price Discovery</strong>: Commodity trading markets have provided a transparent platform to farmers. This has helped in easy and real price discovery in the market. Prior to commodity trading markets, farmers were often easily looted by corrupt middlemen who used to buy from farmers cheaply and sell at a high price to traders. But with a centralized commodity trading exchange, the farmer’s interests are protected.</p><p><strong>2. Better Quality of Commodities</strong>: Since commodity trading markets have strict rules on the quality of commodities traded on the exchange, the farmers are also paying special attention to growing top-notch commodities.</p><p><strong>3. Better Price Risk Management</strong>: With commodity derivatives, farmers have various efficient price risk mitigation tools like futures and options.</p><p><strong>4. Ease of Information</strong>: A central commodity trading market has helped farmers get access to information through free SMS, dedicated TV show ‘mandi.com’, and awareness and training programs throughout the country.</p><h3 id="currency-derivatives" tabindex="-1">Currency (Derivatives) <a class="header-anchor" href="#currency-derivatives" aria-label="Permalink to &quot;Currency (Derivatives)&quot;">​</a></h3><p>For Indian Currency Market read this document <a href="https://zerodha-common.s3.ap-south-1.amazonaws.com/Varsity/Modules/Module%208_Currency%20and%20Commodity%20Futures.pdf" target="_blank" rel="noreferrer">PDF</a>.</p><h3 id="forex-market" tabindex="-1">Forex Market <a class="header-anchor" href="#forex-market" aria-label="Permalink to &quot;Forex Market&quot;">​</a></h3><h4 id="forex-fx-pairs-to-trade" tabindex="-1">Forex (FX) pairs to trade? <a class="header-anchor" href="#forex-fx-pairs-to-trade" aria-label="Permalink to &quot;Forex (FX) pairs to trade?&quot;">​</a></h4><p>Did you know that many professional and institutional traders only focus on one or two currencies<br> or only a few another trading instruments? The reason for that is to enable them to become really<br> proficient with the instrument they chose.</p><p>Now I’m going to break down the risk of trading too many pairs in greater detail, in addition to<br> how you can choose the right currency pairs to trade.</p><h4 id="correlation-excessive-risk-exposure" tabindex="-1">Correlation &amp; Excessive risk exposure <a class="header-anchor" href="#correlation-excessive-risk-exposure" aria-label="Permalink to &quot;Correlation &amp; Excessive risk exposure&quot;">​</a></h4><p>The more some instruments behave like each other, the more correlated they are. If two<br> instruments have 100 % correlation, it means that they move the same way. If their correlation is<br> -100%, then they move in exact opposites. These are the extremes of the scale, but in reality, the<br> correlation numbers are somewhere in between. Here is a forex correlation table (from <a href="https://www.mataf.net/" target="_blank" rel="noreferrer">www.Mataf.net</a>) with major FX pairs to give you an idea about the correlation numbers:</p><p><img src="'+C+'" alt="Forex-Correlation-Table"></p><p>Forex Correlation Table</p><p>In this picture you can, for example, see that correlation between EUR/USD and USD/JPY is -4.8%. This is a really low correlation, and it means that those currency pairs move quite differently and independently to each other.</p><p>If you want to make your instrument list bigger, you need to accept the fact that there will be more and more instruments with pretty high correlation. Unfortunately, there isn’t a simple way to get rid of the correlation problem because the markets are connected. If there is for example event like US Presidential election, you can be sure that a lot of markets and instruments will be affected and the price movements will be very similar in many markets.</p><p>I don’t see a problem with having an open position at that time (if it is part of your trading strategy, of course). Where I DO see a problem is when you trade too many instruments, and suddenly you are in too many HEAVILY correlated positions that all get triggered because of the Presidential election! This is called <strong>Excessive risk exposure</strong>, and it is a problem which you want to avoid.</p><p>It doesn’t have to be an extreme situation like that; sometimes there is something as simple as a USD rally. When this happens, all the pairs where one of the currency is USD move in unison. If you trade too many instruments with USD, you can find yourself in a pretty messy situation with, for example, 5 open trades all dependent on how the USD will move. Most likely all those 5 trades will end the same way, and that is just too much risk! If you were an institutional trader, you would probably get sacked for doing that.</p><p>So, my advice is this: don’t trade too many instruments/currencies with high correlation. If you do, make sure you have rules that prevent you from taking on too much risk. For example, don’t open more than two USD positions. This is an extremely simple trade management rule, but it’s massively powerful.</p><p>You can also halve your positions if you see that you are going to enter a trade on two heavily correlated instruments. Remember that you need to feel comfortable with losses as this cannot be avoided from time to time. What we don’t want though, is a single macroeconomic news event to hit us for 3-4 losing trades at once because we forgot they were all heavily correlated.</p><h4 id="being-overwhelmed" tabindex="-1">Being overwhelmed <a class="header-anchor" href="#being-overwhelmed" aria-label="Permalink to &quot;Being overwhelmed&quot;">​</a></h4><p>Another problem that comes with trading too many currency pairs or other trading instruments is that it’s just really complicated to handle all the trades. If you want to be successful in trading, then the execution of your strategy needs to be basically flawless. You need to focus and follow the rules of your trading strategy 100%. Everything needs to be managed perfect – analysis, entry, exit, position management, money management.</p><p>Apart from that, you also need to know which macroeconomic news will impact the instrument/s you are trading and how large the impact will likely be. All that is doable if you focus on only a few trading instruments, but it is much harder when you trade 10+ of them on the intraday basis.</p><h4 id="choosing-the-right-currency-pair" tabindex="-1">Choosing the right currency pair <a class="header-anchor" href="#choosing-the-right-currency-pair" aria-label="Permalink to &quot;Choosing the right currency pair&quot;">​</a></h4><p>At first, you need to consider the costs of trading. These consist of spread, broker commission, and swap. Generally speaking, <strong>the bigger the Market Share percentage, the lower the trading costs</strong>. Here are the most liquid currency pairs (pairs with the biggest Market Share):</p><p><img src="'+S+'" alt="Pairs-with-Biggest-Market-Share"></p><p>Pairs with Biggest Market Share</p><p>I also need to mention that the costs of trading can fluctuate based on the instrument volatility. Generally speaking, <strong>the higher the volatility, the bigger the costs</strong> will be to trade the instrument (spreads mostly). You also need to be aware of the various instruments volatility in your trading strategy. This will require you to adjust your SL and PT accordingly to the volatility of the asset you are trading. Also, the strategy itself should be consistent with that currency pairs volatility and behavior. Some pairs are good for fast, aggressive trading, while still others are better for slower and calmer trades.</p><p>Here is a <strong>Daily Range table</strong> (average from the last 10 weeks) of various currency pairs to give you some overall picture of their average volatility.</p><p><img src="'+N+'" alt="Daily-Range-Table"></p><p>Daily Range Table</p><p>In my trading, I prefer to avoid GBP pairs. If you look at the table, you can see that they are one of the most volatile. The GBP also tends to aggressively spike past major support and resistance zones, which doesn’t really suit my trading strategy as well as many of the others. For that reason, I usually avoid trading the British Pound.</p><h4 id="major-currency-characteristics" tabindex="-1">Major currency characteristics <a class="header-anchor" href="#major-currency-characteristics" aria-label="Permalink to &quot;Major currency characteristics&quot;">​</a></h4><p>Every currency pair is unique and has its own characteristics. There isn’t a universal rule that would tell you which pair to trade and which to avoid. As I mentioned before, you need to go through them and see for yourself which ones fit you and your strategy best.</p><p>To give you some initial idea’s and to help you get started, I wrote out the characteristics of some pairs as I see them. I hope it can help you in choosing the right instruments for your own trading.</p><p><strong>EUR/USD</strong></p><ul><li>Excellent winning ratio with volume-based strategies. This pair is number one for me!</li><li>The most liquid pair.</li><li>The cheapest to trade.</li><li>Average volatility.</li><li>If something significant is happening in the markets, the EUR/USD will “tell” you.</li></ul><p><strong>AUD/USD</strong></p><ul><li>Slow. Sometimes you really need to be patient, but on the other hand, you have plenty of time to think when managing your positions.</li><li>Less volatile.</li><li>Cheap to trade.</li><li>Good and precise reactions to volume-based S/R zones.</li><li>Commodity currency (depends on commodity prices and commodity-related news).</li><li>China dependent – reacts to China-related news because Australia has a lot of business bonds with China.</li></ul><p><strong>USD/CAD</strong></p><ul><li>More volatile.</li><li>Not as cheap as other major FX pairs, but still good even for intraday trading.</li><li>Good reactions to volume-based S/R zones but sometimes not so precise (sometimes shoots past levels and turns later).</li><li>Very reactive to oil-related news and oil prices.</li><li>Sometimes higher correlation with AUD/USD because of the oil and other commodities (CAD is a commodity currency).</li></ul><p><strong>USD/JPY</strong></p><ul><li>More volatile.</li><li>Cheap to trade (mostly because of high liquidity).</li><li>Very precise reactions to volume-based S/R (even though it is volatile).</li><li>Capable of spikes and big crazy moves.</li><li>Safe heaven currency (uncertainty in the markets -&gt; people buy JPY).</li></ul><p><strong>GBP/USD</strong></p><ul><li>Volatile.</li><li>Moderately cheap to trade.</li><li>Hard to predict. Sometimes reacts sooner to volume-based S/R zones, sometimes too late, sometimes never.</li><li>Usually quite “dead” during the Asian session.</li><li>Good for catching trends (you need to be ready to quit fast though).</li><li>Quick spike moves.</li><li>Massive reactions to UK CPI news and BREXIT related news, not so much on GBP Rate Decision news (for now).</li></ul><p>If I had to choose two of these major pairs to trade with my Volume Profile trading strategy, I would choose EUR/USD and USD/JPY. The reason I would select those two is that they are both cheap to trade, have good reactions to my volume-based S/R levels, and there is a very low correlation between these two pairs. Additionally, I can also use the same pip size for my take profit and Stop-loss which makes trade execution much easier.</p><p>This is just the way I personally see it. In the end, I think that it is best for you to do your own research and make your own opinion on what currencies are the best to trade. I will be happy if this helps you find someplace to start from and if it gives you an idea what things to consider when looking for the ideal set of instruments to trade.</p><h4 id="favorite-fx-trading-instruments" tabindex="-1">Favorite FX Trading Instruments <a class="header-anchor" href="#favorite-fx-trading-instruments" aria-label="Permalink to &quot;Favorite FX Trading Instruments&quot;">​</a></h4><p>Here are three approaches intraday trading, swing trading, and long-term investments.</p><p>As far as intraday trading is concerned, We have these four major pairs that are good to trade: EUR/USD, AUD/USD, USD/CAD and USD/JPY.</p><p>For swing trading and long-term investment methods which not so time-consuming and they are also pretty easily manageable. For that reason, you can trade swing trades and long-term investment trades as an addition to your intraday trades. My preferred forex pairs for that are: AUD/CAD, AUD/CHF, AUD/JPY, AUD/NZD, AUD/USD, CAD/JPY, EUR/GBP, EUR/JPY, EUR/USD, GBP/USD, CHF/JPY, NZD/CAD, NZD/USD, USD/CHF, USD/JPY and USD/CAD.</p><p><strong>BONUS:</strong></p><h3 id="best-cryptocurrencies-to-trade" tabindex="-1">Best cryptocurrencies to trade <a class="header-anchor" href="#best-cryptocurrencies-to-trade" aria-label="Permalink to &quot;Best cryptocurrencies to trade&quot;">​</a></h3><p>If you are into intraday trading or swing trading the cryptocurrencies, then I suggest you focus only on the most liquid – the ones with the biggest market capitalization. Big market capitalization means good liquidity, better spreads and a smaller chance of slippage. The absolute winner is obviously Bitcoin. Other ones that follow are for example Ethereum or Ripple. Below, you can see a table with the ten cryptocurrencies based on Market Cap.</p><p><img src="'+P+'" alt="10-Cryptocurrencies-based-on-Market-Cap"></p><p>10 Cryptocurrencies based on Market Cap</p><p>The cryptocurrency market is pretty young, so this table is liable to change continuously. You can see the up-to-date version here: <a href="https://coinmarketcap.com/" target="_blank" rel="noreferrer">https://coinmarketcap.com/</a></p><p>Another thing you should consider is <strong>volatility</strong>. You need the market to move to make money. Instruments that go sideways many days, then jump suddenly and then go sideways again really aren’t ideal for trading. At least not for intraday or swing trades.</p><p>That’s it for all the <strong>Market Segments Basics Explained</strong>.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',269)),a(o,null,{default:d(()=>[a(i)]),_:1})])}const L=r(E,[["render",q]]);export{_ as __pageData,L as default};
